sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
half4 main(float2 coord) {
    float2 h = size * 0.5;
    float2 p = (coord - h) / h;
    if (abs(p.x) >= 1.0 || abs(p.y) >= 1.0) return image.eval(coord);
    float2 e = 1.0 - p * p;
    float w = e.x * e.y;
    return image.eval(h + p * (1.0 - strength * 0.6 * w) * h);
}
